<script setup lang="ts">
import { computed } from 'vue'
import type { DraftCatalog } from '@/api/types'
import type { ReviewObject, ReviewState, ReviewVariable } from '@/drafting/source-review-types'
import { alignmentGroup, baselineProposals, baselineVariables, businessVariable, catalogLabel, compatibleBaseline, suggestedBaselines, variableKind } from '@/drafting/variable-catalog'
import DraftingQuestionPicker from './DraftingQuestionPicker.vue'
const props = defineProps<{ catalog: DraftCatalog; state: ReviewState; draft: ReviewObject; locale: string; disabled?: boolean }>()
const emit = defineEmits<{ align: [id: string, alignment: ReviewObject]; add: [key: string, reason: string]; exclude: [key: string, reason: string | null]; inspect: [id: string] }>()
const t = (zh: string, en: string) => props.locale === 'en' ? en : zh
const typeLabel = (kind: string) => ({ boolean:t('是／否','Yes / no'),number:t('数字','Number'),text:t('文字','Text'),date:t('日期','Date'),choice:t('单选','Single choice'),multiselect:t('多选','Multiple choices'),record:t('资料组','Record'),list:t('明细变量','Repeated details') }[variableKind(kind)] ?? t('需核对类型','Review value type'))
const alignmentLabel = (status: string) => ({ matched:t('已对应基准','Baseline matched'),new:t('新变量','New variable'),ambiguous:t('歧义待核','Ambiguous'),unreviewed:t('待人工审核','Awaiting review') }[status] ?? t('待人工审核','Awaiting review'))
const fields = computed(() => baselineVariables(props.catalog))
const nodes = computed(() => props.state.variables.filter(businessVariable))
const classify = (node: ReviewVariable) => alignmentGroup(node, fields.value, props.state, props.catalog.ruleVersion)
const choices = computed(() => nodes.value.filter(node => classify(node) === props.draft.tab).map(node => ({ id: node.id, label: (props.locale === 'en' ? node.nameEn : node.nameZh) + (node.catalogAlignment?.confirmed ? t(' · 已确认对齐', ' · Alignment confirmed') : t(' · 待审核', ' · To review')), searchText: [node.nameZh, node.nameEn, ...(node.sourceAnchors ?? []).map(anchor => anchor.text)].join(' ') })))
const selected = computed(() => nodes.value.find(node => node.id === props.draft.nodeId))
const suggestions = computed(() => selected.value ? suggestedBaselines(selected.value, fields.value, props.state) : [])
const proposals = computed(() => selected.value ? baselineProposals(selected.value, fields.value, props.state, props.draft.scope ?? '') : [])
const compatible = computed(() => selected.value ? fields.value.filter(field => compatibleBaseline(selected.value!, field, props.state, props.draft.scope ?? '')) : [])
const baselineChoices = computed(() => compatible.value.map(field => ({ id: field.baselineKey, label: catalogLabel(field.label, props.locale) + (field.parentKey ? ' · ' + catalogLabel(fields.value.find(parent => parent.baselineKey === field.parentKey)?.label, props.locale) : ''), searchText: Object.values(field.label).join(' ') + ' ' + Object.values(field.description ?? {}).join(' ') })))
const selectedBaseline = computed(() => fields.value.find(field => field.baselineKey === props.draft.baselineKey))
const canMatch = computed(() => !!selected.value && !!selectedBaseline.value && compatibleBaseline(selected.value, selectedBaseline.value, props.state, props.draft.scope ?? '') && (!props.draft.proposalVersion || props.draft.proposalVersion === props.catalog.ruleVersion && !proposals.value.some(proposal => proposal.baselineKey === props.draft.baselineKey && !proposal.compatible)))
const definitionDetails = computed(() => selectedBaseline.value ? fields.value.filter(field => field.baselineKey === selectedBaseline.value!.baselineKey || field.baselineKey.startsWith(selectedBaseline.value!.baselineKey + '.')) : [])
const relationshipFields = computed(() => definitionDetails.value.filter(field => field.condition?.all?.length || field.affects?.length))
const exclusions = computed(() => props.state.catalogReview?.exclusions ?? {})
const missing = computed(() => fields.value.filter(field => !nodes.value.some(node => node.catalogAlignment?.confirmed && node.catalogAlignment.baselineKey === field.baselineKey && node.catalogAlignment.baselineVersion === props.catalog.ruleVersion) && exclusions.value[field.baselineKey]?.baselineVersion !== props.catalog.ruleVersion))
const missingChoices = computed(() => missing.value.map(field => ({ id: field.baselineKey, label: catalogLabel(field.label, props.locale), searchText: Object.values(field.label).join(' ') })))
const missingField = computed(() => missing.value.find(field => field.baselineKey === props.draft.missingKey))
function selectNode() { props.draft.baselineKey = selected.value?.catalogAlignment?.baselineKey ?? (suggestions.value.length === 1 && selected.value?.catalogAlignment?.proposalStatus !== 'ambiguous' ? suggestions.value[0]?.baselineKey : '') ?? ''; props.draft.proposalVersion = ''; props.draft.reason = ''; props.draft.scope = selected.value?.catalogAlignment?.scope ?? '' }
const proposalStateLabel = (status?: string) => ({ matched:t('已有固定变量对应建议，等待人工确认。','A baseline correspondence is proposed and awaits human confirmation.'),ambiguous:t('对应存在歧义或定义不相容，请逐项核对。','Correspondence is ambiguous or definitions differ; review the candidates.'),unmatched:t('本次未找到固定变量对应，单列为未匹配候选，仍需人工核对。','No baseline correspondence was found; retain this unmatched candidate for human review.'),unavailable:t('本次未取得匹配建议，仍可从固定变量目录人工对照。','Matching suggestions were unavailable; you can still review the fixed-variable catalogue manually.') }[status ?? ''] ?? t('尚无语义对应建议；下方同名建议和目录搜索仍可人工核对。','No semantic correspondence is recorded; exact-name hints and catalogue search remain available for manual review.'))
const issueLabel = (code: string) => ({ type_mismatch:t('值类型不同','Value types differ'),unit_mismatch:t('单位不同或尚未明确','Units differ or are missing'),option_domain_mismatch:t('允许取值不同','Allowed values differ'),optional_mismatch:t('必答／选填要求不同','Required/optional settings differ'),parent_mapping_required:t('须先核对所属资料组的对应','Review the parent record correspondence first'),child_mapping_required:t('必需明细的对应关系待核对','Required detail mappings need review'),parent_mismatch:t('所属资料组不同','Parent records differ'),baseline_version_changed:t('建议所用基准版本已变化，请重新对照当前定义','The proposed baseline version changed; review the current definition'),baseline_unavailable:t('原建议的固定变量已不可用','The proposed fixed variable is unavailable'),role_mismatch:t('变量用途不同，需先核对定义','Variable roles differ; review the definition'),definition_mismatch:t('定义仍需核对','The definition needs review') }[code] ?? t('存在尚待核对的定义差异','A definition difference needs review'))
function conditionHint(term: ReviewObject, field: ReviewObject) {
  const input = fields.value.find(item => item.baselineKey === term.field || item.baselineKey === (field.parentKey ? field.parentKey + '.' : '') + term.field)
  const operator = ({ eq:t('等于','equals'),gt:t('大于','greater than'),includes:t('包含','includes'),in:t('属于','is one of'),countGt:t('条目数大于','item count greater than'),includesComponent:t('包括该组成项','includes component'),unknown:t('尚未知','is unknown') } as Record<string,string>)[term.operator] ?? t('判断方式待核对','operator needs review')
  const values = (Array.isArray(term.value) ? term.value : [term.value]).map(value => { const option = input?.options?.find(item => item.value === value); return option ? catalogLabel(option.label, props.locale) : typeof value === 'boolean' ? value ? t('是','yes') : t('否','no') : value === null || value === undefined ? t('未知','unknown') : typeof value === 'object' ? JSON.stringify(value) : String(value) })
  return [catalogLabel(input?.label, props.locale) || t('关联固定变量待核对','Related baseline variable needs review'), operator, ...(term.operator === 'unknown' ? [] : values)].join(' ')
}
function align(status: string) {
  if (!selected.value || !props.draft.reason?.trim() || status === 'matched' && !canMatch.value) return
  emit('align', selected.value.id, { status, confirmed: status !== 'ambiguous', reason: props.draft.reason.trim(), ...(status === 'matched' ? { baselineKey: props.draft.baselineKey, baselineVersion: props.catalog.ruleVersion } : {}), ...(props.draft.scope?.trim() ? { scope: props.draft.scope.trim() } : {}) })
}
</script>
<template>
  <fieldset class="catalog-review" :disabled="disabled" data-catalog-review>
    <legend>{{ t('变量基准对齐审核', 'Review variable alignment') }}</legend>
    <p>{{ t('基准定义与识别结果均须人手核对。对齐保留变量、来源、条件和修改位置；不会采用候选值。基准未识别不等于必需补入。', 'Review both baseline definitions and identified variables. Alignment preserves variables, sources, conditions and amendment locations without adopting candidate values. Missing baseline entries are not automatically required.') }}</p>
    <nav><button v-for="[key, zh, en] in [['matched','对应建议／已确认','Proposed / confirmed matches'],['missing','固定变量未对应','Unassigned fixed variables'],['new','未匹配／新增候选','Unmatched / new candidates'],['ambiguous','歧义待核','Ambiguous'],['unavailable','建议未取得','Suggestions unavailable']]" :key="key" type="button" class="btn" :aria-pressed="draft.tab === key" :data-catalog-tab="key" @click="draft.tab=key;draft.nodeId='';draft.reason=''">{{ t(zh!,en!) }}</button></nav>
    <template v-if="draft.tab !== 'missing'">
      <DraftingQuestionPicker v-model="draft.nodeId" v-model:query="draft.query" :items="choices" :locale="locale" :label="t('选择候选变量', 'Select a candidate variable')" :empty-label="t('请选择变量', 'Choose a variable')" search-attribute="data-catalog-variable-search" context="variables" @change="selectNode" />
      <template v-if="selected">
        <h4>{{ locale === 'en' ? selected.nameEn : selected.nameZh }}</h4>
        <p>{{ t('值类型', 'Value type') }}: {{ typeLabel(selected.type.kind) }} {{ selected.type.unit || '' }} · {{ selected.definitionScope || t('项目范围', 'Project scope') }}</p>
        <blockquote v-for="(anchor,index) in selected.sourceAnchors" :key="index">{{ anchor.text }}</blockquote>
        <p data-catalog-proposal-state>{{ proposalStateLabel(selected.catalogAlignment?.proposalStatus) }}</p>
        <article v-for="(proposal,index) in proposals" :key="proposal.baselineKey+':'+index" class="catalog-proposal" :data-catalog-proposal="proposal.baselineKey">
          <strong>{{ catalogLabel(proposal.field?.label,locale) || t('原建议固定变量已不可用','Proposed fixed variable unavailable') }}</strong><p>{{ proposal.reason }}</p><blockquote v-if="proposal.sourceQuote">{{ proposal.sourceQuote }}</blockquote>
          <p v-for="issue in proposal.issues" :key="issue" class="proposal-issue">{{ issueLabel(issue) }}</p><details v-if="proposal.originalIssues?.length"><summary>{{ t('匹配时记录的定义差异（保留记录）','Definition differences recorded during matching') }}</summary><p v-for="issue in proposal.originalIssues" :key="issue">{{ issueLabel(issue) }}</p></details><button v-if="proposal.field" type="button" class="btn" :data-catalog-view-proposal="proposal.baselineKey" @click="draft.baselineKey=proposal.baselineKey;draft.proposalVersion=proposal.baselineVersion">{{ t('查看这项固定定义','Inspect this fixed definition') }}</button>
        </article>
        <p v-if="!selected.catalogAlignment?.proposalStatus && suggestions.length">{{ t('同名且定义形状相容的旧图建议，仍需核对语义：', 'Legacy exact-name and compatible-shape hints; review their meaning: ') }}{{ suggestions.map(field => catalogLabel(field.label,locale)).join('；') }}</p>
        <p v-if="selected.catalogAlignment">{{ t('已记录', 'Recorded') }}: {{ alignmentLabel(selected.catalogAlignment.status) }} · {{ selected.catalogAlignment.reason }}</p>
        <DraftingQuestionPicker v-model="draft.baselineKey" v-model:query="draft.baselineQuery" :items="baselineChoices" :locale="locale" :label="t('对应固定变量', 'Fixed variable correspondence')" :empty-label="t('请选择对应固定变量', 'Choose a fixed variable')" search-attribute="data-catalog-baseline-search" context="baseline" @change="draft.proposalVersion=''" />
        <p>{{ t('只列出类型、单位、选项、必填性和明细归属相容的基准；需要调整定义时请打开变量编辑。明细变量须将必需列一并对应，再保存审核。', 'Only compatible types, units, options, optionality and detail memberships are listed. Edit the variable to correct a definition. Match required detail columns before saving.') }}</p>
        <section v-if="selectedBaseline" data-catalog-definition><h4>{{ t('固定变量定义（待人工对照）','Fixed definition for human review') }} · {{ catalogLabel(selectedBaseline.label,locale) }}</h4><p>{{ catalogLabel(selectedBaseline.description,locale) }}</p><table><thead><tr><th>{{ t('变量／组成项','Variable / component') }}</th><th>{{ t('值类型／单位','Value type / unit') }}</th><th>{{ t('回答要求','Answer requirement') }}</th><th>{{ t('允许取值','Allowed values') }}</th></tr></thead><tbody><tr v-for="field in definitionDetails" :key="field.baselineKey"><td>{{ catalogLabel(field.label,locale) }}</td><td>{{ typeLabel(field.kind) }} {{ field.unit || '' }}</td><td>{{ field.optional ? t('选填','Optional') : t('必答','Required') }}</td><td>{{ field.options?.map(option=>catalogLabel(option.label,locale) || String(option.value)).join('；') || t('按定义填写','As defined') }}</td></tr></tbody></table><p v-if="!canMatch" class="proposal-issue">{{ t('当前变量定义或建议版本尚不相容；请打开变量编辑补齐类型、单位、选项或归属，再对照确认。原建议继续保留。','The current definition or proposed version is incompatible. Edit the variable type, unit, options or ownership, then review it again. The proposal is retained.') }}</p></section>
        <section v-if="selectedBaseline" data-catalog-relation-hints><h4>{{ t('固定目录中的已知关系提示','Known relationships in the fixed catalogue') }}</h4><p>{{ t('这些适用条件和文件落点供人工对照当前原件。确认变量对应不会覆盖原子拆解的条件、关系或修改范围；关系适用性与原件位置须另行核对。','Review these applicability conditions and file destinations against the current originals. Confirming correspondence preserves the atomic conditions, relationships and amendment ranges; applicability and source locations need separate review.') }}</p><p v-if="!relationshipFields.length">{{ t('此定义未登记固定关系提示。','No fixed relationship hint is recorded for this definition.') }}</p><article v-for="field in relationshipFields" :key="field.baselineKey"><strong>{{ catalogLabel(field.label,locale) }}</strong><ul v-if="field.condition?.all?.length"><li v-for="(term,index) in field.condition.all" :key="index">{{ t('适用条件（同时满足）','Applicability (all conditions)') }}: {{ conditionHint(term,field) }}</li></ul><p v-for="(target,index) in field.affects" :key="index">{{ t('目录文件落点','Catalogue destination') }}: {{ target.document }} {{ target.clause }} {{ target.paragraphs || '' }}</p></article></section>
        <label>{{ t('适用范围（同一基准在不同范围重复时必填）', 'Scope (required for distinct uses of the same baseline)') }}<input v-model="draft.scope" data-catalog-scope /></label>
        <label>{{ t('人工审核理由', 'Review reason') }}<textarea v-model="draft.reason" data-catalog-reason /></label>
        <button class="btn" type="button" data-catalog-confirm-match :disabled="!draft.reason?.trim() || !canMatch" @click="align('matched')">{{ t('人工确认采用这项固定变量定义', 'Confirm this fixed variable definition') }}</button>
        <button class="btn" type="button" data-catalog-confirm-new :disabled="!draft.reason?.trim()" @click="align('new')">{{ t('确认为新变量', 'Confirm new variable') }}</button>
        <button class="btn" type="button" data-catalog-ambiguous :disabled="!draft.reason?.trim()" @click="align('ambiguous')">{{ t('保留歧义待核', 'Retain for review') }}</button>
        <button class="btn" type="button" data-catalog-inspect @click="emit('inspect',selected.id)">{{ t('编辑变量／拆分／合并', 'Edit, split or merge variable') }}</button>
      </template>
    </template>
    <template v-else>
      <DraftingQuestionPicker v-model="draft.missingKey" v-model:query="draft.missingQuery" :items="missingChoices" :locale="locale" :label="t('基准中尚未对应的变量', 'Unmatched baseline variables')" :empty-label="t('请选择基准变量', 'Choose a baseline variable')" search-attribute="data-catalog-missing-search" context="missing" />
      <template v-if="missingField"><p>{{ catalogLabel(missingField.description,locale) }} · {{ typeLabel(missingField.kind) }} {{ missingField.unit || '' }}</p><p v-if="missingField.parentKey">{{ t('补入列变量时一并补齐所属明细组的定义；已有对应变量保留，不导入任何项目值。', 'Adding a column also completes its detail group definitions. Existing matches are kept and no project values are imported.') }}</p><label>{{ t('补入或不适用的人工理由', 'Reason for adding or excluding') }}<textarea v-model="draft.reason" data-catalog-missing-reason /></label><button type="button" class="btn" data-catalog-add-missing :disabled="!draft.reason?.trim()" @click="emit('add',missingField.baselineKey,draft.reason.trim())">{{ t('补入此变量及所属明细定义', 'Add variable and its detail group definitions') }}</button><button type="button" class="btn" data-catalog-exclude :disabled="!draft.reason?.trim()" @click="emit('exclude',missingField.baselineKey,draft.reason.trim())">{{ t('本项目不适用', 'Not applicable to this project') }}</button></template>
      <ul><li v-for="(entry,key) in exclusions" :key="key">{{ catalogLabel(fields.find(field => field.baselineKey === key)?.label,locale) || key }} · {{ entry.reason }}<button type="button" class="btn" @click="emit('exclude',String(key),null)">{{ t('重新核对', 'Review again') }}</button></li></ul>
    </template>
  </fieldset>
</template>
<style scoped>
.catalog-review{margin:16px 0;padding:16px;border:1px solid var(--line);border-radius:6px}.catalog-review>p{font-size:13px;color:var(--muted)}nav{display:flex;gap:8px;flex-wrap:wrap}nav [aria-pressed=true]{background:var(--accent-soft)}label{display:block;margin:12px 0}input,textarea{display:block;width:100%;font:inherit;padding:8px;box-sizing:border-box}blockquote{max-height:130px;overflow:auto;white-space:pre-wrap;font-size:12px}.btn{margin:4px}
</style>
